        """kind is "homework" or "quiz"."""
        if kind not in ("homework", "quiz"):
            raise ValueError(f"Unknown assignment kind: {kind!r}")
        if name in self._assignments:
            raise ValueError(f"Assignment already exists: {name!r}")
        if weight < 0:
            raise ValueError("Weight must be non-negative")
        self._assignments[name] = _Assignment(float(weight), kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if assignment not in self._assignments:
            raise KeyError(f"Unknown assignment: {assignment!r}")
        if not (GRADE_MIN <= grade <= GRADE_MAX):
            raise ValueError(
                f"Grade {grade} is outside the scale {GRADE_MIN}-{GRADE_MAX}"
            )
        self._grades.setdefault(student, {})[assignment] = float(grade)

    def average(self, student: str) -> float:
        student_grades = self._grades.get(student, {})
        dropped_quiz = self._lowest_quiz_to_drop(student_grades)

        total_weight = 0.0
        weighted_sum = 0.0
        for name, assignment in self._assignments.items():
            if name == dropped_quiz:
                continue
            grade = student_grades.get(name, DEFAULT_MISSING_GRADE)
            weighted_sum += assignment.weight * grade
            total_weight += assignment.weight

        return round(weighted_sum / total_weight, 2) if total_weight else 0.0

    def _lowest_quiz_to_drop(self, student_grades: dict[str, float]) -> str | None:
        recorded_quizzes = [
            name
            for name, assignment in self._assignments.items()
            if assignment.kind == "quiz" and name in student_grades
        ]
        if len(recorded_quizzes) <= 1:
            return None
        return min(recorded_quizzes, key=student_grades.__getitem__)
